        ToolReferenceEntry("arch_gameplay_faction_armor", "GUILD EQUIPMENT", "Guild armor follows promotion", "Joining the Guards or Araxos unlocks the corresponding basic outfit. Later swordsman, crossbowman and hunter armors depend on that guild route and promotion. A high stat by itself does not unlock a faction reward.", source = "https://docs.google.com/spreadsheets/d/1Z5O00oK-OYpmjtniR5t3s__TxNq8eMuwzn8ftJPeNpQ/edit#gid=1839435141"),
