        ToolReferenceEntry("arch_gameplay_smith_trainer", "TRAINERS", "Odgar’s militia smithing limit changed", "Patch 1.2.3 made Odgar teach smithing through the skilled level for militia members. Do not use an older guide that treats his teaching limit as unchanged for that route.", source = "https://steamcommunity.com/games/1467450/announcements/detail/3218396987408269215"),
        ToolReferenceEntry("arch_gameplay_alchemy_trainer", "TRAINERS", "Yezegan can teach master alchemy", "Since patch 1.2.3, Yezegan teaches potion brewing through master level. Recipe possession and the required crafting skill are separate checks.", source = "https://steamcommunity.com/games/1467450/announcements/detail/3218396987408269215"),
        ToolReferenceEntry("arch_gameplay_bear_sale", "HUNTING & TRADING", "Sell the Gluttonous Bear skin to Frida", "Patch 1.2.4 added a sale option for this specific trophy with Frida. Keep the trophy if you intend to use that dialogue rather than selling it through ordinary trading.", source = "https://steamcommunity.com/games/1467450/announcements/detail/3294958655383840622"),
        ToolReferenceEntry("arch_gameplay_fang_sale", "HUNTING & TRADING", "Markus buys Seashark fangs", "Patch 1.2.4 added the specific fang sale dialogue with Markus. Patch 1.2.5 also added fang extraction to his teaching options.", source = "https://steamcommunity.com/games/1467450/announcements/detail/5241644120323512700"),
        ToolReferenceEntry("arch_gameplay_hunting_costs", "TRAINERS", "Old hunting prices may be wrong", "Patch 1.2.6 corrected hunting-skill learning costs in some conversations. Treat prices copied from older guides as historical rather than guaranteed current charges.", source = "https://steamcommunity.com/games/1467450/announcements/detail/3395173894695725565"),
        ToolReferenceEntry("arch_gameplay_apples", "FOOD", "Apple-based bonuses were corrected", "Patch 1.2.3 fixed strength-bonus counting for apples and dishes containing them. This is a gameplay calculation fix, not a new damage or armor stat; use the patched game when planning food bonuses.", source = "https://steamcommunity.com/games/1467450/announcements/detail/3218396987408269215"),
